function validateSubmission(p,a){if(!p||p.kind!=='submission'||p.format!=='readingcoach-exchange'||p.schemaVersion!==2||!idOK(p.id)||p.assignmentId!==a.id||!cleanText(p.studentCode,80)||!p.studentCode.trim()||!Array.isArray(p.attempts))throw Error('交卷包格式或作業識別碼不符。');if(p.attempts.length!==a.bank.questions.length||new Set(p.attempts.map(x=>x.qid)).size!==p.attempts.length)throw Error('交卷題數或識別碼不符。');const comp=C.compile(a.bank);for(const item of p.attempts){const q=a.bank.questions.find(q=>q.id===item.qid);if(!q||item.questionVersion!==a.versions[q.id])throw Error('交卷的題目版本不符。');if(!cleanText(item.answer)||!item.answer.trim()||!item.fields||!C.answerComplete(q,{fields:item.fields},q.answerParts)||item.answer!==C.assembleAnswer({fields:item.fields},q.answerParts))throw Error('交卷答案內容不完整或版本資料不一致。');if(!Array.isArray(item.evidence)||item.evidence.some(id=>!comp.sentences[id]||!q.passages.includes(comp.sentences[id].passage)))throw Error('交卷的原文證據無法定位。');const clean=C.sanitizeDraft({...item,mode:'guided',practiceMode:item.firstAttempt?.practiceMode||'independent',requirements:[],checks:{},step:2},comp.questions.find(x=>x.id===q.id),q.answerParts,comp.sentences);if(item.firstAttempt&&stable(clean.firstAttempt)!==stable(item.firstAttempt))throw Error('首答格式不符，請重新匯出交卷包。');if(!Array.isArray(item.supportLog)||!Array.isArray(item.revisions))throw Error('交卷缺支援或修訂歷程。');}return p;}
