function validateFeedback(p,sub,a){if(!p||p.format!=='readingcoach-exchange'||p.schemaVersion!==2||p.kind!=='feedback'||!idOK(p.id)||p.assignmentId!==a.id||p.submissionId!==sub.id||p.studentCode!==sub.studentCode)throw Error('回饋包與這份交卷不符。');feedback(sub,a,p.reviewer,p.reviews);return p;}
